/*
 * A376602  Inflection and undulation points in the sequence of composite
 *          numbers (A002808).
 * https://oeis.org/A376602
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = index (starting at 1) of a composite where the second
 *            difference between consecutive composites is zero. The sequence
 *            is generated by scanning the composite numbers and recording
 *            indices i such that the gap between C_i and C_{i+1} equals the
 *            gap between C_{i-1} and C_i. No closed known for...
 * Range:     u8 n <= 166, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime.h"   /* is_prime(idx_t) */

/* External types defined by the build environment */
extern seq_t a(idx_t n);

seq_t a(idx_t n)
{
        /* cache of already found terms */
        static seq_t *cache = NULL;
        static size_t cache_used = 0;   /* number of terms stored */
        static size_t cache_cap  = 0;   /* cache capacity */

        /* state for scanning composite numbers */
        static uint64_t last_comp      = 0;   /* most recent composite */
        static uint64_t prev_comp      = 0;   /* previous composite */
        static seq_t   last_gap        = 0;   /* last gap computed */
        static bool    have_last_gap   = false;
        static idx_t   composites_done = 0;   /* how many composites have been seen */

        /* generate terms until we have at least n terms cached */
        while (cache_used < (size_t)n) {
                /* initialise on first call */
                if (composites_done == 0) {
                        last_comp = 4;          /* first composite */
                        composites_done = 1;
                        have_last_gap = false;
                        continue;
                }

                /* find next composite after last_comp */
                uint64_t cand = last_comp + 1;
                while (is_prime(cand)) cand++;

                /* update state */
                prev_comp = last_comp;
                last_comp = cand;
                composites_done++;

                seq_t gap = (seq_t)last_comp - (seq_t)prev_comp;

                if (have_last_gap) {
                        if (gap == last_gap) {
                                seq_t val = (seq_t)(composites_done - 2);
                                /* grow cache if necessary */
                                if (cache_used >= cache_cap) {
                                        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                                        seq_t *tmp = (seq_t *)realloc(cache,
                                                                   new_cap * sizeof(seq_t));
                                        if (!tmp) {
                                                abort();   /* allocation failure */
                                        }
                                        cache = tmp;
                                        cache_cap = new_cap;
                                }
                                cache[cache_used++] = val;
                        }
                } else {
                        have_last_gap = true;
                }

                last_gap = gap;
        }

        /* return nth term (1‑based) */
        return cache[(size_t)n - 1];
}
